import random

puntos = [(1, 1), (1.5, 2), (3, 4), (5, 7), (3.5, 5), (4.5, 5), (3.5, 4.5)]

def distancia(a, b):
    return ((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2) ** 0.5

random.seed(21)
k = 2
centroides = random.sample(puntos, k)

for _ in range(10):
    clusters = [[] for _ in range(k)]
    for punto in puntos:
        idx = min(range(k), key=lambda i: distancia(punto, centroides[i]))
        clusters[idx].append(punto)
    nuevos_centroides = []
    for cluster in clusters:
        if cluster:
            x = sum(p[0] for p in cluster) / len(cluster)
            y = sum(p[1] for p in cluster) / len(cluster)
            nuevos_centroides.append((round(x, 3), round(y, 3)))
        else:
            nuevos_centroides.append(centroides[len(nuevos_centroides)])
    if nuevos_centroides == centroides:
        break
    centroides = nuevos_centroides

inercia = round(
    sum(min(distancia(p, c) ** 2 for c in centroides) for p in puntos), 3
)

print(f"centroides finales: {centroides}")
for i, cluster in enumerate(clusters):
    print(f"cluster {i}: {sorted(cluster)}")
print(f"inercia (suma de distancias al cuadrado): {inercia}")
